  const out = {renderer: gl.getParameter(dbg.UNMASKED_RENDERER_WEBGL), vendor: gl.getParameter(dbg.UNMASKED_VENDOR_WEBGL), cbf: !!gl.getExtension('EXT_color_buffer_float'), flin: !!gl.getExtension('OES_texture_float_linear')};
