  void main(){ vec2 u=gl_FragCoord.xy/vec2(1920.,1080.); float a=0.; for(int i=0;i<200;i++){ a+=sin(u.x*float(i)*0.3+t)*cos(u.y*float(i)*0.2-t); } o=vec4(a*0.01+0.5,u,1); }`;
  function sh(type, src){ const s=gl.createShader(type); gl.shaderSource(s,src); gl.compileShader(s); if(!gl.getShaderParameter(s,gl.COMPILE_STATUS)) throw gl.getShaderInfoLog(s); return s; }
  const pr=gl.createProgram(); gl.attachShader(pr,sh(gl.VERTEX_SHADER,vs)); gl.attachShader(pr,sh(gl.FRAGMENT_SHADER,fs)); gl.linkProgram(pr); gl.useProgram(pr);
  const b=gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER,b); gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);
  gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0,2,gl.FLOAT,false,0,0);
  const px = new Uint8Array(1920*1080*4);
  let t0=performance.now();
  for(let i=0;i<30;i++){ gl.uniform1f(gl.getUniformLocation(pr,'t'),i*0.1); gl.drawArrays(gl.TRIANGLES,0,3); gl.readPixels(0,0,1920,1080,gl.RGBA,gl.UNSIGNED_BYTE,px); }
  out.renderRead_ms = (performance.now()-t0)/30;
  t0=performance.now();
  for(let i=0;i<30;i++){ await fetch('/sink',{method:'POST',body:px}); }
  out.post_ms=(performance.now()-t0)/30;
  out.sample=Array.from(px.slice(0,8));
