    // websocket
    const ws=new WebSocket('ws://127.0.0.1:8932'); ws.binaryType='arraybuffer';
    await new Promise(r=>ws.onopen=r);
    t0=performance.now();
    for(let i=0;i<20;i++){ ws.send(buf); await new Promise(r=>ws.onmessage=r); }
    out[name+'_ws']=(performance.now()-t0)/20; ws.close();
  }
  return out;
};
</script></body></html>
