// Minimal WebGL2 helpers: programs, float render targets, fullscreen passes.

export const W = 1920;
export const H = 1080;

export function createGL(canvas) {
  const gl = canvas.getContext('webgl2', {
    antialias: false, alpha: false, depth: false, stencil: false,
    preserveDrawingBuffer: false, powerPreference: 'high-performance',
  });
  if (!gl) throw new Error('webgl2 unavailable');
  if (!gl.getExtension('EXT_color_buffer_float')) throw new Error('no float rt');
  gl.getExtension('OES_texture_float_linear');
  return gl;
}

function compile(gl, type, src, name) {
  const s = gl.createShader(type);
  gl.shaderSource(s, src);
  gl.compileShader(s);
  if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) {
    const log = gl.getShaderInfoLog(s);
    const lines = src.split('\n').map((l, i) => `${i + 1}: ${l}`).join('\n');
    throw new Error(`shader ${name} failed:\n${log}\n${lines}`);
  }
  return s;
}

export function program(gl, vs, fs, name = '?') {
  const p = gl.createProgram();
  gl.attachShader(p, compile(gl, gl.VERTEX_SHADER, vs, name + '.vs'));
  gl.attachShader(p, compile(gl, gl.FRAGMENT_SHADER, fs, name + '.fs'));
  gl.linkProgram(p);
  if (!gl.getProgramParameter(p, gl.LINK_STATUS)) throw new Error(`link ${name}: ${gl.getProgramInfoLog(p)}`);
  const uniforms = {};
  const n = gl.getProgramParameter(p, gl.ACTIVE_UNIFORMS);
  for (let i = 0; i < n; i++) {
    const info = gl.getActiveUniform(p, i);
    uniforms[info.name.replace(/\[0\]$/, '')] = { loc: gl.getUniformLocation(p, info.name), type: info.type, size: info.size };
  }
  return { gl, p, uniforms, name, texUnit: 0 };
}

// Set uniforms by name; unknown names are ignored so scenes can pass supersets.
export function use(prog, u = {}) {
  const gl = prog.gl;
  gl.useProgram(prog.p);
  prog.texUnit = 0;
  for (const k in u) setUniform(prog, k, u[k]);
}

export function setUniform(prog, k, v) {
  const gl = prog.gl;
  const info = prog.uniforms[k];
  if (!info) return;
  const L = info.loc;
  switch (info.type) {
    case gl.FLOAT: info.size > 1 ? gl.uniform1fv(L, v) : gl.uniform1f(L, v); break;
    case gl.FLOAT_VEC2: gl.uniform2fv(L, v); break;
    case gl.FLOAT_VEC3: gl.uniform3fv(L, v); break;
    case gl.FLOAT_VEC4: gl.uniform4fv(L, v); break;
    case gl.INT: case gl.BOOL: gl.uniform1i(L, v); break;
    case gl.FLOAT_MAT4: gl.uniformMatrix4fv(L, false, v); break;
    case gl.FLOAT_MAT3: gl.uniformMatrix3fv(L, false, v); break;
    case gl.SAMPLER_2D: {
      const unit = prog.texUnit++;
      gl.activeTexture(gl.TEXTURE0 + unit);
      gl.bindTexture(gl.TEXTURE_2D, v && v.tex ? v.tex : v);
      gl.uniform1i(L, unit);
      break;
    }
    default: throw new Error('uniform type ' + info.type + ' for ' + k);
  }
}

export function texture(gl, w, h, { internal = gl.RGBA16F, format = gl.RGBA, type = gl.HALF_FLOAT, filter = gl.LINEAR, wrap = gl.CLAMP_TO_EDGE, data = null } = {}) {
