  // Attack/decay envelope summed over recent events. attack in s (smooth rise before/at hit), decay time constant in s.
  pulse(kind, t, decay = 0.18, attack = 0.012, maxBack = 6) {
    const T = this[kind + 'T'];
    const L = this[kind + 's'];
    let i = Audio.lastIdx(T, t + attack);
    let s = 0;
    for (let n = 0; n < maxBack && i >= 0; n++, i--) {
      const dt = t - T[i];
      if (dt > decay * 6) break;
      const str = L[i].s;
      if (dt < 0) s += str * (1 + dt / attack) * (1 + dt / attack); // pre-rise within attack window
      else s += str * Math.exp(-dt / decay);
    }
    return s;
  }

  last(kind, t) {
    const T = this[kind + 'T'];
    const i = Audio.lastIdx(T, t);
    if (i < 0) return { i: -1, dt: 1e9, s: 0, t: -1e9 };
    return { i, dt: t - T[i], s: this[kind + 's'][i].s, t: T[i] };
  }

  count(kind, t0, t1) {
    const T = this[kind + 'T'];
    return Math.max(0, Audio.lastIdx(T, t1) - Audio.lastIdx(T, t0));
  }

  countUpTo(kind, t) { return Audio.lastIdx(this[kind + 'T'], t) + 1; }

  eventsIn(kind, t0, t1) {
    const T = this[kind + 'T'];
    const L = this[kind + 's'];
    const out = [];
    let i = Audio.lastIdx(T, t0) + 1;
    for (; i < T.length && T[i] <= t1; i++) out.push({ t: T[i], s: L[i].s, i });
    return out;
  }

  // Deterministic sixteenth-note "tick" envelope on the grid (the arp plays straight 16ths)
  tick16(t, decay = 0.05) {
    const s16 = this.period / 4;
    const k = Math.floor((t - this.beat0) / s16);
    const dt = t - (this.beat0 + k * s16);
    return { k, env: Math.exp(-dt / decay) };
  }
}

