// Audio signal access: every visual parameter is read from here.

export class Audio {
  async load(base = 'data/') {
    const j = await (await fetch(base + 'audio.json')).json();
    Object.assign(this, j);
    const envBuf = await (await fetch(base + 'env.bin')).arrayBuffer();
    const n = j.env.n;
    const all = new Float32Array(envBuf);
    this.envData = {};
    j.env.names.forEach((name, i) => { this.envData[name] = all.subarray(i * n, (i + 1) * n); });
    this.envRate = j.env.rate;
    this.specData = new Uint8Array(await (await fetch(base + 'spec.bin')).arrayBuffer());
    this.specBins = j.spec.bins;
    this.specN = j.spec.n;
    this.waveData = new Int16Array(await (await fetch(base + 'wave.bin')).arrayBuffer());
    this.kickT = Float64Array.from(this.kicks.map((k) => k.t));
    this.clapT = Float64Array.from(this.claps.map((k) => k.t));
    this.hatT = Float64Array.from(this.hats.map((k) => k.t));
    this.arpT = Float64Array.from(this.arps.map((k) => k.t));
    this.secByKey = {};
    this.sections.forEach((s, i) => { s.index = i; this.secByKey[s.key] = s; });
    return this;
  }

  // --------------------------------------------------------------- grid
  beat(t) { return (t - this.beat0) / this.period; }          // continuous beat index (0 = bar 0 downbeat)
  barf(t) { return (t - this.beat0) / this.bar; }             // continuous bar index
  barT(b) { return this.beat0 + b * this.bar; }
  beatT(b) { return this.beat0 + b * this.period; }
  beatPhase(t) { const b = this.beat(t); return b - Math.floor(b); }
  barPhase(t) { const b = this.barf(t); return b - Math.floor(b); }

  section(t) {
    const S = this.sections;
    for (let i = S.length - 1; i >= 0; i--) if (t >= S[i].t0) return S[i];
    return S[0];
  }

  // --------------------------------------------------------------- envelopes
  env(name, t) {
    const d = this.envData[name];
    const x = t * this.envRate;
    const i = Math.floor(x);
    if (i < 0) return d[0];
    if (i >= d.length - 1) return d[d.length - 1];
    const f = x - i;
    return d[i] * (1 - f) + d[i + 1] * f;
  }

  // mean envelope over a window (for slow, look-around smoothing)
  envAvg(name, t0, t1, steps = 8) {
    let s = 0;
    for (let i = 0; i < steps; i++) s += this.env(name, t0 + (t1 - t0) * (i + 0.5) / steps);
    return s / steps;
  }

  spec(t, out = new Float32Array(64)) {
    const x = t * 60;
    let i = Math.floor(x);
    const f = x - i;
    const B = this.specBins;
    i = Math.max(0, Math.min(this.specN - 2, i));
    for (let k = 0; k < B; k++) out[k] = (this.specData[i * B + k] * (1 - f) + this.specData[(i + 1) * B + k] * f) / 255;
    return out;
  }

  specAt(frame, bin) {
    const i = Math.max(0, Math.min(this.specN - 1, frame | 0));
    return this.specData[i * this.specBins + bin] / 255;
  }

  // stereo sample at time t (linear interp), values in [-1, 1]
  sample(t) {
    const x = t * this.sr;
    const i = Math.floor(x);
    const d = this.waveData;
    const n = d.length / 2;
    if (i < 0 || i >= n - 1) return [0, 0];
    const f = x - i;
    return [
      (d[i * 2] * (1 - f) + d[i * 2 + 2] * f) / 32768,
      (d[i * 2 + 1] * (1 - f) + d[i * 2 + 3] * f) / 32768,
    ];
  }

  // --------------------------------------------------------------- events
  // index of last event with time <= t
  static lastIdx(arr, t) {
    let lo = 0, hi = arr.length - 1, r = -1;
    while (lo <= hi) {
      const m = (lo + hi) >> 1;
      if (arr[m] <= t) { r = m; lo = m + 1; } else hi = m - 1;
    }
    return r;
  }

  // Attack/decay envelope summed over recent events. attack in s (smooth rise before/at hit), decay time constant in s.
  pulse(kind, t, decay = 0.18, attack = 0.012, maxBack = 6) {
    const T = this[kind + 'T'];
    const L = this[kind + 's'];
    let i = Audio.lastIdx(T, t + attack);
    let s = 0;
    for (let n = 0; n < maxBack && i >= 0; n++, i--) {
      const dt = t - T[i];
      if (dt > decay * 6) break;
      const str = L[i].s;
      if (dt < 0) s += str * (1 + dt / attack) * (1 + dt / attack); // pre-rise within attack window
      else s += str * Math.exp(-dt / decay);
    }
    return s;
  }

  last(kind, t) {
    const T = this[kind + 'T'];
    const i = Audio.lastIdx(T, t);
    if (i < 0) return { i: -1, dt: 1e9, s: 0, t: -1e9 };
    return { i, dt: t - T[i], s: this[kind + 's'][i].s, t: T[i] };
  }

  count(kind, t0, t1) {
    const T = this[kind + 'T'];
    return Math.max(0, Audio.lastIdx(T, t1) - Audio.lastIdx(T, t0));
  }

  countUpTo(kind, t) { return Audio.lastIdx(this[kind + 'T'], t) + 1; }

  eventsIn(kind, t0, t1) {
    const T = this[kind + 'T'];
    const L = this[kind + 's'];
    const out = [];
    let i = Audio.lastIdx(T, t0) + 1;
    for (; i < T.length && T[i] <= t1; i++) out.push({ t: T[i], s: L[i].s, i });
    return out;
  }

  // Deterministic sixteenth-note "tick" envelope on the grid (the arp plays straight 16ths)
  tick16(t, decay = 0.05) {
    const s16 = this.period / 4;
    const k = Math.floor((t - this.beat0) / s16);
    const dt = t - (this.beat0 + k * s16);
    return { k, env: Math.exp(-dt / decay) };
  }
}
